/**
 * Generate the Typsidian application icon.
 *
 * Produces `build/icon.png` (1024×1024, transparent background): a violet
 * gradient rounded square with a serif white "T", following the macOS icon
 * proportions (the artwork is inset, so the icns generated by electron-builder
 * sits correctly in the Dock).
 *
 * Rendering goes through headless Chrome (puppeteer-core) so the result is
 * reproducible without any extra image tooling. A Chrome-CLI fallback is kept
 * because puppeteer is a devDependency that could be absent in a bare checkout.
 *
 * Usage: bun scripts/build-icon.mjs
 */

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const output = path.join(repoRoot, 'build', 'icon.png');
const SIZE = 1024;

const CHROME_CANDIDATES = [
  '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  '/Applications/Chromium.app/Contents/MacOS/Chromium',
  process.env.CHROME_PATH,
].filter(Boolean);

const HTML = `<!doctype html>
<html>
<head>
<meta charset="utf-8" />
<style>
  html, body {
    margin: 0;
    padding: 0;
    width: ${SIZE}px;
    height: ${SIZE}px;
    background: transparent;
    overflow: hidden;
  }
  .tile {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 840px;
    height: 840px;
    transform: translate(-50%, -50%);
    border-radius: 190px;
    background:
      radial-gradient(120% 90% at 28% 12%, rgba(255, 255, 255, 0.34) 0%, rgba(255, 255, 255, 0) 52%),
      linear-gradient(148deg, #a78bfa 0%, #7c3aed 46%, #5b21b6 100%);
    /* Inner highlight + bottom shade only: no outer drop shadow, so the PNG
       stays crisp on transparent pixels (macOS adds its own depth). */
    box-shadow:
      inset 0 3px 0 rgba(255, 255, 255, 0.38),
      inset 0 -10px 24px rgba(24, 10, 60, 0.20);
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .glyph {
    font-family: 'New York', 'Iowan Old Style', 'Palatino', 'Georgia', serif;
    font-size: 540px;
    font-weight: 600;
    line-height: 0.78;
    color: #ffffff;
    letter-spacing: -0.02em;
    transform: translateY(-10px);
    text-shadow: 0 8px 22px rgba(32, 12, 78, 0.30);
    /* Optical centering: serif caps sit slightly high and the crossbar makes
       the glyph bottom-heavy. */
    padding-top: 14px;
    user-select: none;
  }
</style>
</head>
<body>
  <div class="tile"><div class="glyph">T</div></div>
</body>
</html>`;

function fail(message) {
  console.error(`[build-icon] ${message}`);
  process.exit(1);
}

fs.mkdirSync(path.dirname(output), { recursive: true });

async function renderWithPuppeteer() {
  const puppeteer = await import('puppeteer-core');
  const executablePath = CHROME_CANDIDATES.find((candidate) => fs.existsSync(candidate));
  if (!executablePath) throw new Error('no Chrome/Chromium executable found');
  const browser = await puppeteer.default.launch({
    executablePath,
    headless: true,
    args: [
      '--hide-scrollbars',
      '--force-device-scale-factor=1',
      '--disable-lcd-text',
      '--allow-file-access-from-files',
    ],
  });
  try {
    const page = await browser.newPage();
    await page.setViewport({ width: SIZE, height: SIZE, deviceScaleFactor: 1 });
    await page.setContent(HTML, { waitUntil: 'load' });
    // Let the serif face and gradients settle before the screenshot.
    await page.evaluate(() => document.fonts?.ready);
    await page.screenshot({ path: output, omitBackground: true, type: 'png' });
  } finally {
    await browser.close();
  }
}

function renderWithChromeCli() {
  const executablePath = CHROME_CANDIDATES.find((candidate) => fs.existsSync(candidate));
  if (!executablePath) throw new Error('no Chrome/Chromium executable found');
  const htmlPath = path.join(os.tmpdir(), 'typsidian-icon.html');
  fs.writeFileSync(htmlPath, HTML, 'utf8');
  const result = spawnSync(
    executablePath,
    [
      '--headless=new',
      '--disable-gpu',
      '--hide-scrollbars',
      '--force-device-scale-factor=1',
      `--window-size=${SIZE},${SIZE}`,
      '--default-background-color=00000000',
      `--screenshot=${output}`,
      `file://${htmlPath}`,
    ],
    { stdio: 'inherit' },
  );
  if (result.status !== 0) throw new Error(`chrome exited with status ${result.status}`);
}

try {
  await renderWithPuppeteer();
} catch (error) {
  console.warn(`[build-icon] puppeteer failed (${error.message}); trying Chrome CLI`);
  renderWithChromeCli();
}

if (!fs.existsSync(output)) fail(`no icon was written to ${output}`);

const size = fs.statSync(output).size;
if (size < 10_000) fail(`icon looks too small (${size} bytes)`);
console.log(`[build-icon] ✔ ${path.relative(repoRoot, output)} (${(size / 1024).toFixed(0)} KB)`);
